 * @since 2026年07月02日
 */
@Getter
@Setter
@Accessors(chain = true)
@TableName("cpq_price_list")
public class PriceListEntity implements Serializable {

    private static final long serialVersionUID = 1L;

    /**
     * 主键
     */
    @TableId(value = "id", type = IdType.AUTO)
    private Long id;

    /**
     * 价目表名称
     */
    @TableField("name")
    private String name;

    /**
     * 价目表编号
     */
    @TableField("price_list_no")
    private String priceListNo;

    /**
     * 价目表类型 0:总部 1:子公司
     */
    @TableField("type")
    private Byte type;

    /**
     * 定价年份
     */
    @TableField("price_year")
    private String priceYear;

    /**
     * 区域ID
     */
    @TableField("region")
    private String region;

    /**
     * 区域名称
     */
    @TableField("region_name")
    private String regionName;

    /**
     * Region English name.
     */
    @TableField("region_name_en")
    private String regionNameEn;

    /**
     * 产品线Id
     */
    @TableField("product_line")
    private String productLine;

    /**
     * 产品线名称
     */
    @TableField("product_line_name")
    private String productLineName;

    /**
     * 出口类型 0供货 1自营
     */
    @TableField("export_type")
    private Byte exportType;

    /**
     * 贸易术语
     */
    @TableField("incoterm")
    private String incoterm;

    /**
     * 起运港
     */
    @TableField("port_of_departure")
    private String portOfDeparture;

    /**
     * 币种
     */
    @TableField("currency")
    private String currency;

    /**
     * 币种名称
     */
    @TableField("currency_name")
    private String currencyName;

    /**
     * 运输模式
     */
    @TableField("international_mode")
    private String internationalMode;

    /**
     * 运输模式名称
     */
    @TableField("international_mode_name")
    private String internationalModeName;

    /**
     * 滚装散杂类型
     */
    @TableField("international_mode_type")
    private String internationalModeType;

    /**
     * 滚装散杂类型名称
     */
    @TableField("international_mode_type_name")
    private String internationalModeTypeName;

    /**
     * 发布状态 0:草稿 1:生效 2:待发布 3:停用 4:失效
     */
    @TableField("status")
    private Byte status;

    /**
     * 版本号
     */
    @TableField("version")
    private String version;

    /**
     * 同步策略（位标记）
     */
    @TableField("sync_policy")
    private Byte syncPolicy;

    /**
     * 定价引擎编号
     */
    @TableField("pricing_engine_no")
    private String pricingEngineNo;

    /**
     * 关联总部价目表编号
     */
    @TableField("parent_no")
    private String parentNo;

    /**
     * 关联总部价目表版本号
     */
    @TableField("parent_version")
    private String parentVersion;

    /**
     * 启用时间
     */
    @TableField("effective_start_time")
    private Date effectiveStartTime;

    /**
     * 结束时间
     */
    @TableField("effective_end_time")
    private Date effectiveEndTime;

    /**
     * 更新部门id
     */
    @TableField("updated_department")
    private String updatedDepartment;

    /**
     * 更新部门名称
     */
    @TableField("updated_department_name")
    private String updatedDepartmentName;

    /**
     * 创建时间
     */
    @TableField("createdAt")
    private String createdAt;

    /**
     * 创建人
     */
    @TableField("createdBy")
    private String createdBy;

    /**
     * 创建人名称
     */
    @TableField("createdByName")
    private String createdByName;

    /**
     * 更新时间
     */
    @TableField("updatedAt")
    private Date updatedAt;

    /**
     * 更新人
     */
    @TableField("updatedBy")
    private String updatedBy;

    /**
     * 更新人名称
     */
    @TableField("updatedByName")
    private String updatedByName;

    /**
     * 是否删除
     */
    @TableField("isDelete")
    @TableLogic
    private Byte isDelete;
}

